    const aliases = { 국어: "국어", 수학: "수학", 영어: "영어", 한국사: "한국사", 사탐: "사회탐구", 사회탐구: "사회탐구", 과탐: "과학탐구", 과학탐구: "과학탐구", 직탐: "직업탐구", 직업탐구: "직업탐구", 제2외국어한문: "제2외국어·한문" };
